// Initial file generated by Claude Sonnet 5.5

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { inFiveMinutes, makeJWT } from "./helpers.ts";

async function freshModule(): Promise<typeof import("@/core/StudentAuth.ts")> {
  vi.resetModules();
  return import("@/core/StudentAuth.ts");
}

// Makes `prompt` return the given answers in order, recording the questions it was asked
function stubPrompt(answers: Array<string | null>): Array<string> {
  const asked: Array<string> = [];
  vi.stubGlobal("prompt", (question: string) => { asked.push(question); return answers.shift() ?? null; });
  return asked;
}

describe("StudentAuth.initUsername", () => {

  afterEach(() => { vi.unstubAllGlobals(); });

  it("trims the name it is given", async () => {
    const auth = await freshModule();
    expect(auth.initUsername("  Ana  ")).toBe("Ana");
  });

  it("falls back to asking when the externally supplied name is unusable", async () => {
    stubPrompt(["Bo"]);
    const auth = await freshModule();
    expect(auth.initUsername("   ")).toBe("Bo");
  });

  it("keeps asking until it gets a usable name", async () => {
    const asked = stubPrompt(["", "   ", "x".repeat(81), "bad\u0007name", "Cy"]);
    const auth  = await freshModule();
    expect(auth.initUsername(null)).toBe("Cy");
    expect(asked).toHaveLength(5);
  });

  it("accepts exactly 60 characters, counting an emoji as one", async () => {
    const auth = await freshModule();
    const name = "😀".repeat(60);
    expect(auth.initUsername(name)).toBe(name);
  });

  it("remembers the name instead of asking again", async () => {
    const asked = stubPrompt(["Di"]);
    const auth  = await freshModule();
    auth.initUsername(null);
    auth.initUsername(null);
    expect(asked).toHaveLength(1);
  });

});

describe("StudentAuth: a name the server rejects", () => {

  beforeEach(() => { vi.spyOn(console, "error").mockImplementation(() => {}); });
  afterEach(() => { vi.unstubAllGlobals(); vi.restoreAllMocks(); });

  function stubServer(freshStatus: number): void {
    vi.stubGlobal("fetch", vi.fn((url: string) => {
      if (url.startsWith("/api/auth/student/refresh")) {
        return Promise.resolve(new Response("no cookie", { status: 401 }));
      }
      if (url.startsWith("/api/auth/student/fresh-cookies")) {
        return Promise.resolve(freshStatus === 200
          ? new Response(makeJWT({ aud: "gallery|student", exp: inFiveMinutes(), sub: "1|Second" }), { status: 200 })
          : new Response("Missing/invalid parameter: username", { status: freshStatus }));
      }
      return Promise.resolve(new Response("unexpected", { status: 500 }));
    }));
  }

  it("is forgotten after a 422, so the next attempt asks again", async () => {
    const asked = stubPrompt(["First", "Second"]);
    stubServer(422);
    const auth = await freshModule();

    await expect(auth.getAuthToken()).resolves.toBeNull();
    stubServer(200);
    await auth.getAuthToken();
    expect(asked).toHaveLength(2);
    expect(auth.getStudentName()).toBe("Second");
  });

  it("is kept after other failures (e.g., rate limiting), so the student is not asked again", async () => {
    const asked = stubPrompt(["First", "Second"]);
    stubServer(429);
    const auth = await freshModule();

    await auth.getAuthToken();
    expect(asked).toHaveLength(1);
  });

});
